B.abU=new A.t("ec-m8-q7","\u0645\u0627 \u0627\u0644\u0630\u064a \u062a\u0645\u0644\u0643\u0647 \u0641\u0639\u0644\u064b\u0627 \u0648\u0645\u0627 \u0627\u0644\u0630\u064a \u0644\u0627 \u062a\u0645\u0644\u0643\u0647 \u0641\u064a \u062a\u062c\u0627\u0631\u062a\u0643 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a\u0629\u061f","What do you actually own and not own in your e-commerce business?",B.alf,B.agj,1,"\u0648\u0645\u0627 \u064a\u0628\u0642\u0649 \u0628\u0639\u062f \u062a\u063a\u064a\u0651\u0631 \u062e\u0648\u0627\u0631\u0632\u0645\u064a\u0629 \u0647\u0648 \u0642\u0627\u0626\u0645\u0629 \u0628\u0631\u064a\u062f\u064a\u0629 \u0623\u0648 \u0631\u0642\u0645 \u062a\u0648\u0627\u0635\u0644 \u0645\u062d\u0641\u0648\u0638 \u0628\u0645\u0648\u0627\u0641\u0642\u0629. \u0644\u0630\u0644\u0643: \u0633\u062c\u0651\u0644 \u0627\u0644\u0646\u0637\u0627\u0642 \u0628\u0627\u0633\u0645\u0643 \u0644\u0627 \u0628\u0627\u0633\u0645 \u0627\u0644\u0645\u0637\u0648\u0651\u0631\u060c \u0648\u0635\u062f\u0651\u0631 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u0648\u0627\u0644\u0637\u0644\u0628\u0627\u062a \u062f\u0648\u0631\u064a\u064b\u0627 \u0648\u0627\u062d\u062a\u0641\u0638 \u0628\u0646\u0633\u062e\u0629 \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u0646\u0635\u0629.","What survives an algorithm change is a mailing list or a phone contact kept with consent. So register the domain in your own name rather than your developer, and export customer and order data regularly, keeping a copy off the platform.")
B.ahp=s(["\u0636\u0639\u0641 \u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0627\u0644\u0645\u0646\u0638\u0650\u0651\u0645\u0629 \u0644\u0644\u0642\u0637\u0627\u0639","\u062d\u0627\u062c\u0632 \u062f\u062e\u0648\u0644 \u0645\u0646\u062e\u0641\u0636 \u064a\u062c\u0639\u0644 \u0627\u0644\u0648\u0639\u062f \u0645\u0635\u062f\u064e\u0651\u0642\u064b\u0627\u060c \u0648\u0642\u0635\u0635 \u0646\u062c\u0627\u062d \u062d\u0642\u064a\u0642\u064a\u0629 \u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u0639\u0627\u0631\u062a\u0647\u0627\u060c \u0648\u0646\u062a\u0627\u0626\u062c \u064a\u0635\u0639\u0628 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646\u0647\u0627","\u0642\u0644\u0629 \u0639\u062f\u062f \u0627\u0644\u0645\u062a\u0627\u062c\u0631 \u0641\u064a \u0627\u0644\u0633\u0648\u0642","\u0627\u0631\u062a\u0641\u0627\u0639 \u0647\u0648\u0627\u0645\u0634 \u0627\u0644\u0631\u0628\u062d \u0645\u0642\u0627\u0631\u0646\u0629 \u0628\u0627\u0644\u0642\u0637\u0627\u0639\u0627\u062a \u0627\u0644\u0623\u062e\u0631\u0649"],t.s)
