B.abS=new A.t("cr-m4-q9","\u0645\u0627 \u0627\u0644\u0623\u0633\u0627\u0633 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u0645\u0643\u0646 \u062a\u062e\u0637\u064a\u0647 \u0642\u0628\u0644 \u0623\u064a \u0634\u064a\u0621 \u062e\u0627\u0635 \u0628\u0627\u0644\u0628\u0644\u0648\u0643\u062a\u0634\u064a\u0646\u061f","What foundation cannot be skipped before anything blockchain-specific?",B.aes,B.axF,1,"\u0644\u064a\u0633\u062a \u062e\u0637\u0648\u0629 \u062a\u0645\u0647\u064a\u062f\u064a\u0629 \u064a\u0645\u0643\u0646 \u0627\u062e\u062a\u0635\u0627\u0631\u0647\u0627: \u0623\u063a\u0644\u0628 \u0645\u0646 \u064a\u0641\u0634\u0644 \u0641\u064a \u062f\u062e\u0648\u0644 \u0627\u0644\u0645\u062c\u0627\u0644 \u0628\u062f\u0623 \u0645\u0646 \u0625\u0637\u0627\u0631 \u0628\u0644\u0648\u0643\u062a\u0634\u064a\u0646 \u062f\u0648\u0646 \u0625\u062a\u0642\u0627\u0646 \u0627\u0644\u0628\u0631\u0645\u062c\u0629 \u0641\u0628\u0642\u064a \u0639\u0646\u062f \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0646\u0633\u062e \u0648\u0627\u0644\u0644\u0635\u0642. \u0648\u0627\u0644\u062e\u0628\u0631 \u0627\u0644\u062c\u064a\u062f \u0623\u0646 \u0627\u0644\u0623\u0633\u0627\u0633 \u0646\u0641\u0633\u0647 \u064a\u0641\u062a\u062d \u0623\u064a \u0645\u0633\u0627\u0631 \u0628\u0631\u0645\u062c\u064a \u0622\u062e\u0631 \u0625\u0646 \u062a\u063a\u064a\u0651\u0631 \u0627\u0644\u0633\u0648\u0642.","This is not a preliminary step you can shorten: most people who fail to enter the field started from a blockchain framework without mastering programming and stayed at copy-and-paste level. The good news is that the same foundation opens any other programming path if the market shifts.")
B.aAd=s(["\u062d\u0641\u0638 \u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0634\u0628\u0643\u0627\u062a \u0648\u0622\u0644\u064a\u0627\u062a\u0647\u0627","\u0623\u0633\u0626\u0644\u0629 \u0644\u0627 \u064a\u062c\u064a\u0628 \u0639\u0646\u0647\u0627 \u0627\u0644\u062d\u0641\u0638: \u0627\u0634\u0631\u062d \u0644\u0645\u0627\u0630\u0627 \u064a\u0635\u0639\u0628 \u062a\u0639\u062f\u064a\u0644 \u0643\u062a\u0644\u0629 \u0642\u062f\u064a\u0645\u0629 \u062f\u0648\u0646 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0643\u0644\u0645\u0629 \xab\u0622\u0645\u0646\xbb\u060c \u0648\u0627\u0634\u0631\u062d \u0627\u0644\u0641\u0631\u0642 \u0628\u064a\u0646 \u0627\u0644\u0645\u062d\u0641\u0638\u0629 \u0648\u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u062e\u0627\u0635 \u0644\u0645\u0646 \u0644\u0645 \u064a\u0633\u0645\u0639 \u0628\u0647\u0645\u0627","\u0639\u062f\u062f \u0627\u0644\u0633\u0627\u0639\u0627\u062a \u0627\u0644\u062a\u064a \u0634\u0627\u0647\u062f\u062a\u0647\u0627","\u0642\u062f\u0631\u062a\u0643 \u0639\u0644\u0649 \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0648\u0631\u0642\u0629 \u0627\u0644\u0623\u0635\u0644\u064a\u0629 \u0628\u0633\u0631\u0639\u0629"],t.s)
