B.aaN=new A.t("cr-m5-q8","\u0645\u0627 \xab\u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0633\u0641\u0631\xbb (travel rule) \u062f\u0648\u0644\u064a\u064b\u0627\u061f","What is the international travel rule?",B.aDQ,B.ak4,1,"\u0648\u0647\u064a \u062c\u0632\u0621 \u0645\u0646 \u0645\u0646\u0638\u0648\u0645\u0629 \u0627\u0639\u0631\u0641 \u0639\u0645\u064a\u0644\u0643 \u0648\u0645\u0643\u0627\u0641\u062d\u0629 \u063a\u0633\u0644 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u062a\u064a \u062a\u0644\u062a\u0632\u0645 \u0628\u0647\u0627 \u0627\u0644\u0645\u0646\u0635\u0627\u062a \u0627\u0644\u0645\u0631\u062e\u064e\u0651\u0635\u0629 \u0639\u0627\u0644\u0645\u064a\u064b\u0627\u060c \u0648\u0644\u0647\u0630\u0627 \u062a\u0637\u0644\u0628 \u0627\u0644\u0647\u0648\u064a\u0629 \u0648\u0645\u0635\u062f\u0631 \u0627\u0644\u0623\u0645\u0648\u0627\u0644.","It is part of the know-your-customer and anti-money-laundering framework that globally licensed platforms are bound by, which is why they ask for identity and source of funds.")
B.adG=s(["\u0634\u0647\u0627\u062f\u0627\u062a \u062f\u0648\u0631\u0627\u062a \u0648\u062d\u0633\u0627\u0628 \u0646\u0634\u0637 \u0639\u0644\u0649 \u0645\u0646\u0635\u0627\u062a \u0627\u0644\u062a\u062f\u0627\u0648\u0644","\u0645\u0633\u062a\u0648\u062f\u0639 \u0639\u0627\u0645 \u0644\u0639\u0642\u0648\u062f \u0645\u0643\u062a\u0648\u0628\u0629 \u0648\u0645\u062e\u062a\u0628\u064e\u0631\u0629 \u0628\u062a\u063a\u0637\u064a\u0629 \u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a \u0648\u0627\u0636\u062d\u0629\u060c \u0648\u0639\u0642\u062f \u0645\u0646\u0634\u0648\u0631 \u0648\u0645\u0648\u062b\u064e\u0651\u0642 \u0639\u0644\u0649 \u0634\u0628\u0643\u0629 \u0627\u062e\u062a\u0628\u0627\u0631 \u0623\u0648 \u0631\u0626\u064a\u0633\u064a\u0629\u060c \u0648\u062a\u0648\u062b\u064a\u0642 \u064a\u0634\u0631\u062d \u0642\u0631\u0627\u0631\u0627\u062a\u0643 \u0627\u0644\u062a\u0635\u0645\u064a\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u062e\u0627\u0637\u0631 \u0627\u0644\u062a\u064a \u0639\u0627\u0644\u062c\u062a\u0647\u0627","\u0639\u062f\u062f \u0645\u062a\u0627\u0628\u0639\u064a\u0646 \u0641\u064a \u0645\u062c\u062a\u0645\u0639\u0627\u062a \u0627\u0644\u0645\u0637\u0648\u0631\u064a\u0646","\u062a\u0631\u062c\u0645\u0629 \u0645\u0642\u0627\u0644\u0627\u062a \u0639\u0646 \u0627\u0644\u0645\u062c\u0627\u0644"],t.s)
