B.a7j=new A.t("cr-m8-q8","\u0645\u0627 \u0627\u0644\u062a\u0635\u0631\u0641 \u0627\u0644\u0635\u062d\u064a\u062d \u062a\u062c\u0627\u0647 \u0635\u0648\u0631\u0629 \u062a\u0631\u062e\u064a\u0635 \u064a\u0631\u0633\u0644\u0647\u0627 \u0645\u0639\u0644\u0646\u061f","What is the right response to a licence image sent by an advertiser?",B.ar3,B.ayx,1,"\u0648\u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u062a\u062a\u063a\u064a\u0631\u060c \u0641\u0623\u0639\u062f \u0627\u0644\u062a\u062d\u0642\u0642 \u0639\u0646\u062f \u0643\u0644 \u0642\u0631\u0627\u0631. \u0648\u0627\u0644\u0645\u0631\u0627\u062c\u0639 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u0645\u0631\u0641\u0642\u0629 \u0623\u0633\u0641\u0644 \u0627\u0644\u062f\u0644\u064a\u0644.","Regulations change, so recheck at every decision. The official references are linked below the guide.")
B.aoe=s(["\u0625\u062a\u0642\u0627\u0646 \u0623\u0633\u0627\u0633 \u0627\u0644\u0628\u0631\u0645\u062c\u0629 \u0648\u0642\u0631\u0627\u0621\u0629 \u0648\u0631\u0642\u0629 \u0628\u064a\u062a\u0643\u0648\u064a\u0646 \u0648\u062a\u0634\u063a\u064a\u0644 \u0645\u062d\u0641\u0638\u0629 \u0639\u0644\u0649 \u0634\u0628\u0643\u0629 \u0627\u062e\u062a\u0628\u0627\u0631","\u062a\u0639\u0644\u0651\u0645 Solidity \u0648\u0646\u0634\u0631 \u0639\u0642\u0648\u062f \u0628\u0633\u064a\u0637\u0629 \u0639\u0644\u0649 Sepolia \u2014 \u0631\u0645\u0632 ERC-20\u060c \u0648\u0639\u0642\u062f \u062a\u0635\u0648\u064a\u062a\u060c \u0648\u0636\u0645\u0627\u0646 \u0645\u0634\u0631\u0648\u0637 \u2014 \u0645\u0639 \u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a \u0644\u0643\u0644 \u062f\u0627\u0644\u0629 \u0648\u062a\u0648\u062b\u064a\u0642 \u0627\u0644\u0643\u0648\u062f \u0639\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u0643\u0634\u0641","\u0627\u0644\u062a\u062e\u0635\u0635 \u0641\u064a \u0627\u0644\u0623\u0645\u0627\u0646 \u0623\u0648 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a","\u0625\u0646\u062c\u0627\u0632 \u0645\u0634\u0631\u0648\u0639 \u0643\u0627\u0645\u0644 \u0648\u062f\u062e\u0648\u0644 \u0645\u0633\u0627\u0628\u0642\u0629 \u062a\u062f\u0642\u064a\u0642"],t.s)
