B.abh=new A.t("cr-m10-q4","\u0623\u064a \u0627\u0644\u0634\u0628\u0643\u0627\u062a \u062a\u0646\u0627\u0633\u0628 \u062a\u0637\u0628\u064a\u0642\u064b\u0627 \u064a\u062d\u062a\u0627\u062c \u062a\u0623\u0643\u064a\u062f\u064b\u0627 \u0633\u0631\u064a\u0639\u064b\u0627 \u0648\u0646\u0647\u0627\u0626\u064a\u064b\u0627 \u0645\u062b\u0644 \u0646\u0642\u0637\u0629 \u0628\u064a\u0639\u061f","Which networks suit an application needing fast final confirmation, such as a point of sale?",B.aeB,B.aeI,1,"\u0623\u0645\u0627 \u0644\u062a\u062e\u0632\u064a\u0646 \u0642\u064a\u0645\u0629 \u0643\u0628\u064a\u0631\u0629 \u0644\u0633\u0646\u0648\u0627\u062a \u0641\u0623\u0645\u0627\u0646 \u0627\u0644\u0634\u0628\u0643\u0629 \u0648\u0639\u0645\u0642\u0647\u0627 \u0623\u0647\u0645 \u0645\u0646 \u0633\u0631\u0639\u062a\u0647\u0627. \u0648\u0647\u0630\u0627 \u0641\u0631\u0642 \u0639\u0645\u0644\u064a \u0644\u0627 \u0646\u0638\u0631\u064a \u0628\u064a\u0646 \u0646\u0648\u0639\u064a \u0627\u0644\u0646\u0647\u0627\u0626\u064a\u0629.","For storing large value for years, the network security and depth matter more than its speed. That is a practical rather than theoretical difference between the two kinds of finality.")
B.aqp=s(["\u0627\u062e\u062a\u0631\u0627\u0642 \u0639\u0642\u062f \u0639\u0628\u0631 \u062b\u063a\u0631\u0629 \u0641\u064a \u0645\u0643\u062a\u0628\u0629 \u062e\u0627\u0631\u062c\u064a\u0629","\u0625\u0639\u0627\u062f\u0629 \u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0627\u062a \u0645\u0646 \u0628\u0648\u062a\u0627\u062a \u0648\u0645\u062f\u0642\u0651\u0642\u064a\u0646 \u0644\u0645\u0635\u0644\u062d\u062a\u0647\u0645 \u0641\u062a\u064f\u0646\u0641\u064e\u0651\u0630 \u0635\u0641\u0642\u062a\u0643 \u0628\u0633\u0639\u0631 \u0623\u0633\u0648\u0623","\u0625\u063a\u0631\u0627\u0642 \u0627\u0644\u0645\u062c\u0645\u0651\u0639 \u0628\u0633\u064a\u0648\u0644\u0629 \u0648\u0647\u0645\u064a\u0629","\u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0629 \u0646\u0641\u0633\u0647\u0627 \u0645\u0631\u062a\u064a\u0646"],t.s)
