B.a8l=new A.t("cr-m10-q5","\u0645\u0627 \xab\u0647\u062c\u0648\u0645 \u0627\u0644\u0634\u0637\u064a\u0631\u0629\xbb (sandwich attack)\u061f","What is a sandwich attack?",B.aqp,B.aAU,1,"\u0648\u0647\u0648 \u0645\u0646 \u0635\u0648\u0631 \u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0627\u0633\u062a\u062e\u0631\u0627\u062c (MEV)\u060c \u0648\u064a\u0642\u0644\u0651 \u0628\u062a\u062d\u062f\u064a\u062f \u062d\u062f\u0648\u062f \u0627\u0644\u0627\u0646\u0632\u0644\u0627\u0642 \u0648\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u062e\u062f\u0645\u0627\u062a \u0625\u0631\u0633\u0627\u0644 \u062e\u0627\u0635\u0629.","It is a form of maximal extractable value (MEV), reduced by setting slippage limits and using private submission services.")
B.adl=s(["\u062a\u0631\u0643\u0647\u0627 \u0644\u0623\u0646 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0644\u0645 \u064a\u0639\u062f \u0645\u0633\u062a\u062e\u062f\u0645\u064b\u0627","\u0625\u0644\u063a\u0627\u0624\u0647\u0627 \u0639\u0628\u0631 \u0623\u062f\u0648\u0627\u062a \u0645\u0631\u0627\u062c\u0639\u0629 \u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0627\u062a\u060c \u0644\u0623\u0646\u0647\u0627 \u062a\u0628\u0642\u0649 \u0633\u0627\u0631\u064a\u0629 \u0625\u0644\u0649 \u0627\u0644\u0623\u0628\u062f","\u062d\u0630\u0641 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0645\u0646 \u0627\u0644\u0645\u062a\u0635\u0641\u062d \u064a\u0643\u0641\u064a","\u0646\u0642\u0644 \u0627\u0644\u0623\u0635\u0648\u0644 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u062d\u0641\u0638\u0629 \u0646\u0641\u0633\u0647\u0627"],t.s)
