B.ahT=s(["\u062a\u0646\u062e\u0641\u0636 \u0627\u0644\u0645\u062e\u0627\u0637\u0631\u0629 \u0644\u0623\u0646 \u0627\u0644\u0647\u0627\u0645\u0634 \u0627\u0644\u0645\u062a\u0627\u062d \u0627\u0631\u062a\u0641\u0639","\u0644\u0627 \u062a\u0646\u062e\u0641\u0636: \u0627\u0644\u0625\u064a\u062f\u0627\u0639 \u064a\u0631\u0641\u0639 \u0627\u0644\u0647\u0627\u0645\u0634 \u0627\u0644\u0645\u062a\u0627\u062d \u0648\u0644\u0627 \u064a\u063a\u064a\u0651\u0631 \u0627\u0644\u0627\u062a\u062c\u0627\u0647 \u0648\u0644\u0627 \u0627\u0644\u062d\u062c\u0645\u060c \u0628\u0644 \u064a\u0632\u064a\u062f \u0627\u0644\u0645\u0628\u0644\u063a \u0627\u0644\u0645\u0639\u0631\u064e\u0651\u0636","\u062a\u062e\u062a\u0641\u064a \u0627\u0644\u0645\u062e\u0627\u0637\u0631\u0629 \u0645\u0627 \u062f\u0627\u0645 \u0627\u0644\u0645\u0631\u0643\u0632 \u0644\u0645 \u064a\u064f\u063a\u0644\u0642","\u062a\u0646\u062e\u0641\u0636 \u0625\u0644\u0649 \u0627\u0644\u0646\u0635\u0641 \u062a\u0642\u0631\u064a\u0628\u064b\u0627 \u0628\u0645\u0636\u0627\u0639\u0641\u0629 \u0627\u0644\u0631\u0635\u064a\u062f"],t.s)
B.ayX=s(["Risk falls because available margin rose","It does not fall: a top-up raises available margin but changes neither direction nor size, and only increases the amount exposed","Risk disappears while the position stays open","Risk roughly halves when you double the balance"],t.s)
B.a7h=new A.t("fx-m3-q1","\u0627\u0642\u062a\u0631\u0628 \u062d\u0633\u0627\u0628\u0643 \u0645\u0646 \u0627\u0644\u062a\u0635\u0641\u064a\u0629 \u0641\u0623\u0648\u062f\u0639\u062a \u0645\u0628\u0644\u063a\u064b\u0627 \u0625\u0636\u0627\u0641\u064a\u064b\u0627. \u0645\u0627 \u0627\u0644\u0623\u062b\u0631 \u0627\u0644\u062d\u0642\u064a\u0642\u064a \u0639\u0644\u0649 \u0627\u0644\u0645\u062e\u0627\u0637\u0631\u0629\u061f","Your account nears liquidation so you deposit more money. What is the real effect on risk?",B.ahT,B.ayX,1,"\u0647\u0630\u0627 \u0623\u0634\u064a\u0639 \u062e\u0637\u0623 \u0642\u0627\u062a\u0644. \u0627\u0644\u062e\u064a\u0627\u0631 \u0627\u0644\u0630\u064a \u064a\u062e\u0641\u0636 \u0627\u0644\u0645\u062e\u0627\u0637\u0631\u0629 \u0641\u0639\u0644\u064b\u0627 \u0647\u0648 \u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u062d\u062c\u0645 \u0644\u0627 \u0625\u0636\u0627\u0641\u0629 \u0631\u0635\u064a\u062f. \u0648\u0627\u0644\u0646\u0638\u0627\u0645 \u064a\u0631\u0627\u0642\u0628 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0647\u0627\u0645\u0634 (\u062d\u0642\u0648\u0642 \u0627\u0644\u0645\u0644\u0643\u064a\u0629 \u0645\u0642\u0633\u0648\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0647\u0627\u0645\u0634 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645): \u062f\u0648\u0646 \u062d\u062f \u0645\u0639\u064a\u0651\u0646 \u064a\u0635\u0644\u0643 \u062a\u0646\u0628\u064a\u0647\u060c \u0648\u062f\u0648\u0646 \u062d\u062f \u0623\u062f\u0646\u0649 \u064a\u063a\u0644\u0642 \u0627\u0644\u0646\u0638\u0627\u0645 \u0645\u0631\u0627\u0643\u0632\u0643 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627 \u2014 \u0648\u0630\u0644\u0643 \u0627\u0644\u0642\u0631\u0627\u0631 \u0644\u064a\u0633 \u0628\u064a\u062f\u0643 \u0648\u063a\u0627\u0644\u0628\u064b\u0627 \u064a\u0642\u0639 \u0639\u0646\u062f \u0623\u0633\u0648\u0623 \u0633\u0639\u0631.","This is the common fatal mistake. The choice that actually reduces risk is reducing size, not adding balance. The system monitors your margin level (equity divided by used margin): below one threshold you get an alert, and below a lower one it closes your positions automatically \u2014 a decision that is not yours and usually lands at the worst possible price.")
B.axG=s(["\u0627\u0633\u0645 \u0627\u0644\u0632\u0648\u062c \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641","\u0627\u0644\u062d\u062c\u0645 \u0648\u0627\u0644\u0645\u062e\u0627\u0637\u0631\u0629: \u0627\u0644\u0646\u0642\u0637\u0629 \u0648\u062d\u062f\u0629 \u062d\u0631\u0643\u0629 \u0644\u0627 \u0642\u064a\u0645\u0629\u060c \u0648\u0642\u064a\u0645\u062a\u0647\u0627 \u0628\u0627\u0644\u0645\u0627\u0644 \u062a\u0639\u062a\u0645\u062f \u0643\u0644\u064a\u064b\u0627 \u0639\u0644\u0649 \u062d\u062c\u0645 \u0627\u0644\u0645\u0631\u0643\u0632","\u062a\u0648\u0642\u064a\u062a \u0627\u0644\u062c\u0644\u0633\u0629 \u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0629","\u0639\u062f\u062f \u0627\u0644\u0635\u0641\u0642\u0627\u062a \u0627\u0644\u064a\u0648\u0645\u064a\u0629"],t.s)
