B.abo=new A.t("fx-m5-q8","\u0644\u0645\u0627\u0630\u0627 \u062a\u0633\u062a\u0645\u0631 \u0623\u0646\u0645\u0627\u0637 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u0644 \u0628\u0627\u0633\u0645 \u0627\u0644\u0641\u0648\u0631\u0643\u0633 \u0628\u0627\u0644\u0634\u0643\u0644 \u0646\u0641\u0633\u0647 \u0633\u0646\u0629 \u0628\u0639\u062f \u0633\u0646\u0629\u061f","Why do fraud patterns in the name of forex keep running in almost the same form year after year?",B.aC9,B.alJ,1,"\u0648\u0644\u0627 \u062a\u062a\u0631\u062f\u062f \u0641\u064a \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u062d\u062a\u0649 \u0644\u0648 \u0644\u0645 \u062a\u062e\u0633\u0631 \u0634\u064a\u0626\u064b\u0627: \u0628\u0644\u0627\u063a\u0643 \u0642\u062f \u064a\u0645\u0646\u0639 \u062e\u0633\u0627\u0631\u0629 \u063a\u064a\u0631\u0643\u060c \u0648\u0627\u0644\u0635\u0645\u062a \u0647\u0648 \u0645\u0627 \u064a\u064f\u0628\u0642\u064a \u0627\u0644\u0646\u0645\u0637 \u0646\u0641\u0633\u0647 \u064a\u0639\u0645\u0644 \u0639\u0644\u0649 \u0627\u0644\u0636\u062d\u064a\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629 \u0628\u0639\u062f \u0623\u0633\u0628\u0648\u0639.","And do not hesitate to report even if you lost nothing: your report may prevent someone else loss, and silence is what lets the same pattern run on the next victim a week later.")
B.auP=s(["\u0646\u0645\u0648\u0630\u062c\u064b\u0627 \u062a\u0646\u0628\u0624\u064a\u064b\u0627 \u0644\u0644\u0633\u0648\u0642","\u0628\u064a\u0627\u0646\u0627\u062a \u0639\u0646 \u0646\u0641\u0633\u0643: \u0647\u0644 \u062a\u062e\u0631\u062c \u0645\u0646 \u0627\u0644\u0631\u0627\u0628\u062d \u0645\u0628\u0643\u0631\u064b\u0627\u061f \u0647\u0644 \u062a\u0632\u064a\u062f \u0627\u0644\u062d\u062c\u0645 \u0628\u0639\u062f \u062e\u0633\u0627\u0631\u0629\u061f \u0647\u0644 \u062a\u062a\u062f\u0627\u0648\u0644 \u0623\u0643\u062b\u0631 \u062a\u062d\u062a \u0627\u0644\u0636\u063a\u0637\u061f","\u0633\u062c\u0644\u064b\u0627 \u0636\u0631\u064a\u0628\u064a\u064b\u0627 \u0645\u0639\u062a\u0645\u062f\u064b\u0627","\u062f\u0644\u064a\u0644\u064b\u0627 \u062a\u0642\u062f\u0651\u0645\u0647 \u0644\u0644\u062c\u0647\u0629 \u0627\u0644\u0631\u0642\u0627\u0628\u064a\u0629"],t.s)
