B.a6B=new A.y3("forex","forex","\u0627\u062e\u062a\u0628\u0627\u0631 \u0633\u0648\u0642 \u0627\u0644\u0639\u0645\u0644\u0627\u062a","FX Knowledge Check","\u0639\u0634\u0631\u0629 \u0623\u0633\u0626\u0644\u0629 \u0645\u0633\u062d\u0648\u0628\u0629 \u0645\u0646 \u0623\u062f\u0644\u0629 \u0633\u0648\u0642 \u0627\u0644\u0639\u0645\u0644\u0627\u062a. \u0644\u0643\u0644 \u0633\u0624\u0627\u0644 \u0625\u062c\u0627\u0628\u0629 \u0648\u0627\u062d\u062f\u0629 \u0635\u062d\u064a\u062d\u0629\u060c \u0648\u064a\u0638\u0647\u0631 \u0634\u0631\u062d\u0647\u0627 \u0641\u0648\u0631 \u0627\u0644\u0625\u062c\u0627\u0628\u0629. \u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0646\u0633\u0628\u0629 \u0645\u0626\u0648\u064a\u0629\u060c \u0648\u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0639\u0634\u0631\u0629 \u0646\u0645\u0627\u0630\u062c \u0645\u062e\u062a\u0644\u0641\u0629: \u0641\u064a \u0643\u0644 \u0645\u0631\u0629 \u062a\u0641\u062a\u062d\u0647 \u064a\u0623\u062a\u064a\u0643 \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u062a\u0627\u0644\u064a \u0628\u0623\u0633\u0626\u0644\u0629 \u062c\u062f\u064a\u062f\u0629.","Ten questions drawn from the currencies guides. Each has one correct answer, and the reasoning appears the moment you answer. The result is a percentage, and the test has ten different models: every time you open it you get the next model, with new questions.","\u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u062a\u0642\u064a\u0633 \u0641\u0647\u0645\u0643 \u0644\u0644\u0645\u0627\u062f\u0629 \u0641\u0642\u0637. \u0644\u0627 \u062a\u0639\u0646\u064a \u0623\u0646 \u0627\u0644\u0645\u0636\u0627\u0631\u0628\u0629 \u0645\u0646\u0627\u0633\u0628\u0629 \u0644\u0643\u060c \u0648\u0644\u0627 \u062a\u0639\u0646\u064a \u0627\u0633\u062a\u0639\u062f\u0627\u062f\u0643 \u0644\u0641\u062a\u062d \u062d\u0633\u0627\u0628\u060c \u0648\u0644\u0627 \u062a\u063a\u0646\u064a \u0639\u0646 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u062a\u0631\u062e\u064a\u0635 \u0623\u064a \u062c\u0647\u0629 \u0644\u062f\u0649 \u0627\u0644\u062c\u0647\u0629 \u0627\u0644\u0631\u0642\u0627\u0628\u064a\u0629 \u0642\u0628\u0644 \u0623\u064a \u0645\u0628\u0644\u063a.","The score measures your understanding of the material only. It does not mean speculation suits you, it does not mean you are ready to open an account, and it does not replace verifying any firm licence with the supervisory authority before any amount of money.",B.ax2)
B.alO=s(["\u062d\u0635\u0629 \u0635\u063a\u064a\u0631\u0629 \u0645\u0646 \u0645\u0644\u0643\u064a\u0629 \u0627\u0644\u0634\u0631\u0643\u0629\u060c \u0628\u0623\u0635\u0648\u0644\u0647\u0627 \u0648\u062f\u064a\u0648\u0646\u0647\u0627 \u0648\u0623\u0631\u0628\u0627\u062d\u0647\u0627","\u0648\u0639\u062f\u064b\u0627 \u0645\u0646 \u0627\u0644\u0634\u0631\u0643\u0629 \u0628\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0645\u0628\u0644\u063a \u0645\u0639 \u0641\u0627\u0626\u062f\u0629","\u062d\u0642\u064b\u0651\u0627 \u0641\u064a \u0645\u0637\u0627\u0644\u0628\u0629 \u0627\u0644\u0634\u0631\u0643\u0629 \u0628\u0633\u0639\u0631 \u0634\u0631\u0627\u0621 \u0645\u062d\u062f\u0651\u062f \u0644\u0627\u062d\u0642\u064b\u0627","\u062a\u0631\u062e\u064a\u0635\u064b\u0627 \u0628\u0627\u0644\u0645\u062a\u0627\u062c\u0631\u0629 \u0639\u0644\u0649 \u0633\u0639\u0631 \u0627\u0644\u0634\u0631\u0643\u0629 \u062f\u0648\u0646 \u0645\u0644\u0643\u064a\u0629"],t.s)
B.aFc=s(["A small slice of ownership in the company, with its assets, debts and profits","A promise from the company to return your money with interest","A right to demand a set purchase price from the company later","A licence to trade on the company price without owning anything"],t.s)
B.a8r=new A.t("st-m1-q1","\u0645\u0627\u0630\u0627 \u062a\u0645\u0644\u0643 \u0641\u0639\u0644\u064b\u0627 \u062d\u064a\u0646 \u062a\u0634\u062a\u0631\u064a \u0633\u0647\u0645\u064b\u0627 \u0648\u0627\u062d\u062f\u064b\u0627\u061f","What do you actually own when you buy one share?",B.alO,B.aFc,0,"\u0627\u0644\u0633\u0647\u0645 \u0645\u0644\u0643\u064a\u0629\u060c \u0644\u0627 \u0642\u0631\u0636 \u0648\u0644\u0627 \u0639\u0642\u062f. \u062d\u0627\u0645\u0644 \u0627\u0644\u0633\u0646\u062f \u0647\u0648 \u0627\u0644\u062f\u0627\u0626\u0646 \u0627\u0644\u0630\u064a \u064a\u064f\u0648\u0639\u062f \u0628\u0641\u0627\u0626\u062f\u0629\u061b \u0623\u0645\u0627 \u0627\u0644\u0645\u0633\u0627\u0647\u0645 \u0641\u064a\u0645\u0644\u0643 \u062d\u0635\u0629 \u0641\u064a \u062d\u0642\u0648\u0642 \u0627\u0644\u0645\u0644\u0643\u064a\u0629 \u0648\u0645\u0627 \u064a\u062a\u0628\u0642\u0651\u0649 \u0628\u0639\u062f \u0633\u062f\u0627\u062f \u0627\u0644\u062c\u0645\u064a\u0639.","A share is ownership, not a loan and not a contract. A bondholder is the lender who is promised interest; a shareholder owns a stake in the equity and a claim on what is left after everyone else is paid.")
B.atc=s(["\u0634\u0631\u0643\u0629 \xab\u0623\xbb\u060c \u0644\u0623\u0646 \u0642\u064a\u0645\u062a\u0647\u0627 \u0627\u0644\u0633\u0648\u0642\u064a\u0629 \u0639\u0634\u0631\u0629 \u0645\u0644\u064a\u0627\u0631\u0627\u062a \u0645\u0642\u0627\u0628\u0644 \u0645\u0644\u064a\u0627\u0631 \u0648\u0627\u062d\u062f","\u0634\u0631\u0643\u0629 \xab\u0628\xbb\u060c \u0644\u0623\u0646 \u0633\u0639\u0631 \u0633\u0647\u0645\u0647\u0627 \u0623\u0639\u0644\u0649 \u0628\u0645\u0626\u0629 \u0645\u0631\u0629","\u0645\u062a\u0633\u0627\u0648\u064a\u062a\u0627\u0646\u060c \u0644\u0623\u0646 \u062d\u0627\u0635\u0644 \u0627\u0644\u0636\u0631\u0628 \u0648\u0627\u062d\u062f","\u0644\u0627 \u064a\u0645\u0643\u0646 \u0645\u0639\u0631\u0641\u0629 \u0630\u0644\u0643 \u0645\u0646 \u0633\u0639\u0631 \u0627\u0644\u0633\u0647\u0645 \u0648\u0639\u062f\u062f\u0647"],t.s)
