B.a7f=new A.t("st-m1-q7","\u0623\u063a\u0644\u0628 \u0627\u0644\u0631\u0628\u062d \u0627\u0644\u062a\u0634\u063a\u064a\u0644\u064a \u0644\u0623\u0645\u0627\u0632\u0648\u0646 \u064a\u0623\u062a\u064a \u0645\u0646 \u0623\u064a \u062c\u0632\u0621 \u0645\u0646 \u0639\u0645\u0644\u0647\u0627\u061f","Most of Amazon operating profit comes from which part of its business?",B.apO,B.asb,0,"\u062a\u062c\u0632\u0626\u0629 \u0623\u0645\u0627\u0632\u0648\u0646 \u0636\u062e\u0645\u0629 \u0627\u0644\u0625\u064a\u0631\u0627\u062f \u0644\u0643\u0646 \u0647\u0627\u0645\u0634\u0647\u0627 \u0631\u0642\u064a\u0642 \u062c\u062f\u064b\u0627\u060c \u0628\u064a\u0646\u0645\u0627 \u064a\u0623\u062a\u064a \u0623\u063a\u0644\u0628 \u0627\u0644\u0631\u0628\u062d \u0627\u0644\u062a\u0634\u063a\u064a\u0644\u064a \u0645\u0646 \u0642\u0633\u0645 \u0627\u0644\u062d\u0648\u0633\u0628\u0629 \u0627\u0644\u0633\u062d\u0627\u0628\u064a\u0629. \u0645\u0646 \u064a\u0646\u0638\u0631 \u0625\u0644\u064a\u0647\u0627 \u0643\u0645\u062a\u062c\u0631 \u064a\u0633\u064a\u0621 \u0641\u0647\u0645 \u0645\u0635\u062f\u0631 \u0623\u0631\u0628\u0627\u062d\u0647\u0627.","Amazon retail is enormous in revenue but very thin in margin, while most operating profit comes from the cloud division. Anyone who sees it as a shop misunderstands where its profits come from.")
B.aBf=s(["\u0644\u0623\u0646 \u0627\u0644\u0631\u0628\u062d \u064a\u062d\u062a\u0645\u0644 \u062a\u0642\u062f\u064a\u0631\u0627\u062a \u0643\u062b\u064a\u0631\u0629\u060c \u0628\u064a\u0646\u0645\u0627 \u0627\u0644\u0646\u0642\u062f \u0625\u0645\u0627 \u062f\u062e\u0644 \u0641\u0639\u0644\u064b\u0627 \u0623\u0648 \u0644\u0645 \u064a\u062f\u062e\u0644","\u0644\u0623\u0646 \u0627\u0644\u0646\u0642\u062f \u064a\u064f\u062f\u0642\u064e\u0651\u0642 \u0645\u0631\u062a\u064a\u0646 \u0648\u0627\u0644\u0631\u0628\u062d \u064a\u064f\u062f\u0642\u064e\u0651\u0642 \u0645\u0631\u0629","\u0644\u0623\u0646 \u0627\u0644\u0646\u0642\u062f \u0644\u0627 \u064a\u0638\u0647\u0631 \u0641\u064a \u0627\u0644\u0642\u0648\u0627\u0626\u0645 \u0627\u0644\u0645\u0627\u0644\u064a\u0629 \u0627\u0644\u0645\u0646\u0634\u0648\u0631\u0629","\u0644\u0623\u0646 \u0627\u0644\u0631\u0628\u062d \u064a\u064f\u062d\u0633\u0628 \u0633\u0646\u0648\u064a\u064b\u0627 \u0648\u0627\u0644\u0646\u0642\u062f \u064a\u064f\u062d\u0633\u0628 \u0634\u0647\u0631\u064a\u064b\u0627"],t.s)
