B.a8F=new A.t("st-m2-q7","\u062d\u064a\u0646 \u062a\u0634\u062a\u0631\u064a \u0633\u0647\u0645\u064b\u0627 \u0645\u0646 \u0627\u0644\u0633\u0648\u0642 \u0627\u0644\u064a\u0648\u0645\u060c \u0645\u0646 \u064a\u062a\u0644\u0642\u0651\u0649 \u0645\u0627\u0644\u0643\u061f","When you buy a share on the market today, who receives your money?",B.axh,B.ahC,0,"\u0627\u0644\u0645\u0627\u0644 \u0627\u0644\u0630\u064a \u064a\u064f\u062c\u0645\u0639 \u0641\u064a \u0627\u0644\u0637\u0631\u062d \u0627\u0644\u0623\u0648\u0644\u064a \u064a\u0630\u0647\u0628 \u0625\u0644\u0649 \u0627\u0644\u0634\u0631\u0643\u0629\u061b \u0623\u0645\u0627 \u0627\u0644\u062a\u062f\u0627\u0648\u0644 \u0628\u0639\u062f \u0630\u0644\u0643 \u0641\u0647\u0648 \u062a\u0628\u0627\u062f\u0644 \u0628\u064a\u0646 \u0627\u0644\u0645\u0633\u062a\u062b\u0645\u0631\u064a\u0646 \u0644\u0627 \u062a\u062a\u0644\u0642\u0651\u0649 \u0627\u0644\u0634\u0631\u0643\u0629 \u0645\u0646\u0647 \u0634\u064a\u0626\u064b\u0627 \u0648\u0644\u0627 \u062a\u0633\u062a\u0641\u064a\u062f \u0645\u0646\u0647 \u0645\u0628\u0627\u0634\u0631\u0629.","Money raised in the initial offering goes to the company; trading afterwards is an exchange between investors from which the company receives nothing and gains nothing directly.")
B.afB=s(["\u0627\u0646\u062e\u0641\u0627\u0636 \u0633\u0639\u0631 \u0627\u0644\u0633\u0647\u0645 \u0664\u0660\u066a \u062e\u0644\u0627\u0644 \u0633\u0646\u0629","\u0646\u0645\u0648 \u0627\u0644\u0630\u0645\u0645 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0623\u0633\u0631\u0639 \u0645\u0646 \u0627\u0644\u0625\u064a\u0631\u0627\u062f","\u0625\u0635\u062f\u0627\u0631 \u0623\u0633\u0647\u0645 \u062c\u062f\u064a\u062f\u0629 \u0644\u062a\u063a\u0637\u064a\u0629 \u0627\u0644\u0645\u0635\u0627\u0631\u064a\u0641 \u0627\u0644\u062a\u0634\u063a\u064a\u0644\u064a\u0629","\u0641\u062c\u0648\u0629 \u0645\u0633\u062a\u0645\u0631\u0629 \u0628\u064a\u0646 \u0627\u0644\u0631\u0628\u062d \u0627\u0644\u0645\u0639\u0644\u0646 \u0648\u0627\u0644\u0646\u0642\u062f \u0627\u0644\u0645\u062a\u0648\u0644\u0651\u062f"],t.s)
B.au7=s(["The share price falling 40% in a year","Receivables growing faster than revenue","Issuing new shares to cover operating costs","A sustained gap between reported profit and cash generated"],t.s)
B.aby=new A.t("st-m2-q8","\u0623\u064a \u0645\u0645\u0627 \u064a\u0644\u064a \u0644\u064a\u0633 \u0641\u064a \u0630\u0627\u062a\u0647 \u0639\u0644\u0627\u0645\u0629 \u0639\u0644\u0649 \u0633\u0647\u0645 \u0633\u064a\u0626\u061f","Which of the following is not, in itself, a sign of a bad stock?",B.afB,B.au7,0,"\u0633\u0647\u0645 \u0647\u0628\u0637 \u0664\u0660\u066a \u0642\u062f \u064a\u0643\u0648\u0646 \u0634\u0631\u0643\u0629 \u0645\u0645\u062a\u0627\u0632\u0629 \u0623\u0635\u0628\u062d\u062a \u0623\u0631\u062e\u0635\u060c \u0623\u0648 \u0634\u0631\u0643\u0629 \u0633\u064a\u0626\u0629 \u0641\u064a \u0637\u0631\u064a\u0642\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0635\u0641\u0631. \u0627\u0644\u0633\u0639\u0631 \u0648\u062d\u062f\u0647 \u0644\u0627 \u064a\u0641\u0631\u0651\u0642 \u0628\u064a\u0646\u0647\u0645\u0627\u061b \u0623\u0645\u0627 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u0627\u0644\u062b\u0644\u0627\u062b\u0629 \u0627\u0644\u0623\u062e\u0631\u0649 \u0641\u062a\u0635\u0641 \u0645\u0627 \u064a\u062d\u062f\u062b \u062f\u0627\u062e\u0644 \u0627\u0644\u0639\u0645\u0644.","A stock down 40% might be an excellent company that got cheaper, or a bad one on its way to zero. Price alone does not distinguish them, whereas the other three describe what is happening inside the business.")
B.aDR=s(["\u0642\u0648\u0629 \u0627\u0644\u062a\u0633\u0639\u064a\u0631: \u0645\u0627 \u064a\u062a\u0628\u0642\u0651\u0649 \u0628\u0639\u062f \u062a\u0643\u0644\u0641\u0629 \u0625\u0646\u062a\u0627\u062c \u0627\u0644\u0645\u0646\u062a\u062c \u0646\u0641\u0633\u0647","\u0643\u0641\u0627\u0621\u0629 \u0627\u0644\u0625\u062f\u0627\u0631\u0629 \u0641\u064a \u062e\u0641\u0636 \u0627\u0644\u0631\u0648\u0627\u062a\u0628","\u0642\u062f\u0631\u0629 \u0627\u0644\u0634\u0631\u0643\u0629 \u0639\u0644\u0649 \u0633\u062f\u0627\u062f \u062f\u064a\u0648\u0646\u0647\u0627","\u0646\u0633\u0628\u0629 \u0627\u0644\u0636\u0631\u0627\u0626\u0628 \u0627\u0644\u062a\u064a \u062a\u062f\u0641\u0639\u0647\u0627 \u0627\u0644\u0634\u0631\u0643\u0629"],t.s)
