B.acu=new A.t("st-m3-q1","\u0634\u0631\u0643\u0629 \u0642\u0633\u0651\u0645\u062a \u0643\u0644 \u0633\u0647\u0645 \u0625\u0644\u0649 \u0623\u0631\u0628\u0639\u0629 \u0623\u0633\u0647\u0645. \u0645\u0627\u0630\u0627 \u064a\u062d\u062f\u062b \u0644\u0642\u064a\u0645\u0629 \u0645\u0627 \u062a\u0645\u0644\u0643\u0647\u061f","A company splits each share into four. What happens to the value of your holding?",B.auT,B.akC,0,"\u0627\u0644\u062a\u062c\u0632\u0626\u0629 \u0644\u0627 \u062a\u062e\u0644\u0642 \u0642\u064a\u0645\u0629 \u0648\u0644\u0627 \u062a\u062f\u0645\u0651\u0631\u0647\u0627. \u0648\u0644\u0647\u0630\u0627 \u062a\u064f\u0639\u062f\u064e\u0651\u0644 \u0627\u0644\u0623\u0633\u0639\u0627\u0631 \u0627\u0644\u062a\u0627\u0631\u064a\u062e\u064a\u0629 \u0644\u0644\u062a\u062c\u0632\u0626\u0629 \u0642\u0628\u0644 \u0645\u0642\u0627\u0631\u0646\u062a\u0647\u0627 \u2014 \u0648\u0625\u0644\u0627 \u0628\u062f\u062a \u0627\u0644\u062a\u062c\u0632\u0626\u0629 \u0648\u0643\u0623\u0646\u0647\u0627 \u0627\u0646\u0647\u064a\u0627\u0631 \u0641\u064a \u0627\u0644\u0633\u0639\u0631.","A split neither creates nor destroys value. This is why historical prices are adjusted for splits before comparison \u2014 otherwise a split would look like a price collapse.")
B.ao7=s(["\u0643\u0644 \u0627\u0644\u0634\u0631\u0643\u0627\u062a \u0641\u064a \u0627\u0644\u0645\u0624\u0634\u0631 \u0628\u0623\u0648\u0632\u0627\u0646\u0647\u0627\u060c \u062f\u0648\u0646 \u0645\u062d\u0627\u0648\u0644\u0629 \u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u0631\u0627\u0628\u062d\u064a\u0646","\u0623\u0641\u0636\u0644 \u0639\u0634\u0631 \u0634\u0631\u0643\u0627\u062a \u0641\u064a \u0627\u0644\u0645\u0624\u0634\u0631 \u062d\u0633\u0628 \u0623\u062f\u0627\u0621 \u0627\u0644\u0639\u0627\u0645 \u0627\u0644\u0645\u0627\u0636\u064a","\u0627\u0644\u0634\u0631\u0643\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u062e\u062a\u0627\u0631\u0647\u0627 \u0645\u062f\u064a\u0631 \u0627\u0644\u0635\u0646\u062f\u0648\u0642 \u0634\u0647\u0631\u064a\u064b\u0627","\u0639\u0642\u0648\u062f\u064b\u0627 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0624\u0634\u0631 \u062f\u0648\u0646 \u0627\u0645\u062a\u0644\u0627\u0643 \u0623\u0633\u0647\u0645"],t.s)
